#include <algorithm>
#include <cmath>

class Solution {
public:
    int sumKDigitNumbers(long long low, long long high, int k) {
        long long MOD = 1e9 + 7;
        long long k_min = 1;
        for (int i = 1; i < k; ++i) k_min *= 10;
        long long k_max = k_min * 10 - 1;
        long long start = std::max(low, k_min);
        long long end = std::min(high, k_max);
        if (start > end) return 0;
        long long count = (end - start + 1) % MOD;
        long long sum_ends = (start + end) % MOD;
        long long total = (sum_ends * count) % MOD;
        // multiply by modular inverse of 2
        return (total * 500000004) % MOD;
    }
};

class Solution {
    public int sumKDigitNumbers(long low, long high, int k) {
        long MOD = 1_000_000_007;
        long kMin = 1;
        for (int i = 1; i < k; i++) kMin *= 10;
        long kMax = kMin * 10 - 1;
        long start = Math.max(low, kMin);
        long end = Math.min(high, kMax);
        if (start > end) return 0;
        long count = (end - start + 1) % MOD;
        long sumEnds = (start + end) % MOD;
        long total = (sumEnds * count) % MOD;
        return (int) ((total * 500000004) % MOD);
    }
}

function sumKDigitNumbers(low, high, k) {
    const MOD = 1000000007n;
    const kMin = 10n ** BigInt(k - 1);
    const kMax = 10n ** BigInt(k) - 1n;
    const l = BigInt(low), h = BigInt(high);
    const start = l > kMin ? l : kMin;
    const end = h < kMax ? h : kMax;
    if (start > end) return 0;
    const count = end - start + 1n;
    const total = ((start + end) * count / 2n) % MOD;
    return Number(total);
}
